-- Additive only: new fields and tables; no DROP, DELETE or rebuild.
CREATE TABLE `contents_watch_themes` (
	`order` integer NOT NULL,
	`parent_id` integer NOT NULL,
	`value` text,
	`id` integer PRIMARY KEY NOT NULL,
	FOREIGN KEY (`parent_id`) REFERENCES `contents`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `contents_watch_keywords` (
	`order` integer NOT NULL,
	`parent_id` integer NOT NULL,
	`value` text,
	`id` integer PRIMARY KEY NOT NULL,
	FOREIGN KEY (`parent_id`) REFERENCES `contents`(`id`) ON UPDATE no action ON DELETE cascade
);
ALTER TABLE "contents" ADD COLUMN "emotional_core" TEXT;
ALTER TABLE "contents" ADD COLUMN "watch_kind" TEXT;
ALTER TABLE "contents" ADD COLUMN "playback_source" TEXT DEFAULT 'none';
