	`order` integer NOT NULL,
	`parent_id` integer NOT NULL,
	`value` text,
	`id` integer PRIMARY KEY NOT NULL,
	FOREIGN KEY (`parent_id`) REFERENCES `_contents_v`(`id`) ON UPDATE no action ON DELETE cascade
);
ALTER TABLE "_contents_v" ADD COLUMN "version_emotional_core" TEXT;
ALTER TABLE "_contents_v" ADD COLUMN "version_watch_kind" TEXT;
ALTER TABLE "_contents_v" ADD COLUMN "version_playback_source" TEXT DEFAULT 'none';
ALTER TABLE "_contents_v" ADD COLUMN "version_playback_u_r_l" TEXT;
ALTER TABLE "_contents_v" ADD COLUMN "version_playback_file_id" INTEGER REFERENCES "media"("id") ON DELETE SET NULL;
CREATE TABLE `watch_rails_themes` (
	`order` integer NOT NULL,
	`parent_id` text NOT NULL,
	`value` text,
	`id` integer PRIMARY KEY NOT NULL,
	FOREIGN KEY (`parent_id`) REFERENCES `watch_rails`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `watch_rails_keywords` (
	`order` integer NOT NULL,
	`parent_id` text NOT NULL,
