	`_order` integer NOT NULL,
	`_parent_id` text NOT NULL,
	`id` text PRIMARY KEY NOT NULL,
	`content_id` integer NOT NULL,
	FOREIGN KEY (`content_id`) REFERENCES `contents`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`_parent_id`) REFERENCES `watch_rails`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `watch_rails` (
	`_order` integer NOT NULL,
	`_parent_id` integer NOT NULL,
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`mode` text DEFAULT 'automatic',
	`limit` numeric DEFAULT 6,
	FOREIGN KEY (`_parent_id`) REFERENCES `watch`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `watch` (
	`id` integer PRIMARY KEY NOT NULL,
	`show_samples` integer DEFAULT true,
	`updated_at` text,
	`created_at` text
);
CREATE TABLE `watch_rels` (
	`id` integer PRIMARY KEY NOT NULL,
	`order` integer,
	`parent_id` integer NOT NULL,
	`path` text NOT NULL,
	`characters_id` integer,
	FOREIGN KEY (`parent_id`) REFERENCES `watch`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`characters_id`) REFERENCES `characters`(`id`) ON UPDATE no action ON DELETE cascade
);
