CREATE TABLE "production_containers" (
	"id" integer PRIMARY KEY NOT NULL,
	"title" text NOT NULL,
	"slug" text NOT NULL,
	"description" text,
	"cover_id" integer,
	"cover_mobile_id" integer,
	"url" text,
	"updated_at" text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	"created_at" text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	FOREIGN KEY ("cover_id") REFERENCES "media"("id") ON UPDATE no action ON DELETE set null,
	FOREIGN KEY ("cover_mobile_id") REFERENCES "media"("id") ON UPDATE no action ON DELETE set null
);
CREATE TABLE "production_containers_rels" (
	"id" integer PRIMARY KEY NOT NULL,
	"order" integer,
	"parent_id" integer NOT NULL,
	"path" text NOT NULL,
	"watch_terms_id" integer,
	FOREIGN KEY ("parent_id") REFERENCES "production_containers"("id") ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY ("watch_terms_id") REFERENCES "watch_terms"("id") ON UPDATE no action ON DELETE cascade
);
