-- Additive schema extension
CREATE TABLE "pages_blocks_character_moments_images" (
	"_order" integer NOT NULL,
	"_parent_id" text NOT NULL,
	"id" text PRIMARY KEY NOT NULL,
	"image_id" integer,
	"mobile_image_id" integer,
	"title" text,
	"caption" text,
	"alt" text,
	"focal_x" numeric,
	"focal_y" numeric,
	"content_id" integer,
	"href" text,
